package com.cekalix.controlador;
import com.cekalix.dao.UsuarioDAO;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/usuarios")
public class UsuarioServlet extends HttpServlet {private final UsuarioDAO dao=new UsuarioDAO();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{q.setAttribute("usuarios",dao.listar());q.getRequestDispatcher("/WEB-INF/vistas/usuarios.jsp").forward(q,p);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{try{String k=q.getParameter("clave");if(k==null||k.length()<8)throw new IllegalArgumentException("La contraseña debe tener al menos 8 caracteres.");dao.crear(q.getParameter("nombre"),q.getParameter("usuario"),k,q.getParameter("rol"));p.sendRedirect(q.getContextPath()+"/usuarios");}catch(Exception e){q.getSession().setAttribute("error",e.getMessage());p.sendRedirect(q.getContextPath()+"/usuarios");}}}